using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using MapSharedProps.EditorTools;
public static class Wood98Checks {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static void Check(bool v,string s){if(!v)throw new Exception(s);}
 static Dictionary<string,GameObject> Build(string stage){string folder="Assets/Imported98-"+stage;Check(!AssetDatabase.IsValidFolder(folder),"Fresh test output required");AssetDatabase.CreateFolder("Assets",folder.Substring(7));var root=new GameObject("Wood props "+stage);var p=new Dictionary<string,GameObject>();Check(SmallPropsV1.Build(Path.Combine(Root,"Input98-"+stage),folder,root.transform,Shader.Find("MapSharedProps/Lit"),p)==2&&p.Count==43,"43 prefabs/two placements");PrefabUtility.SaveAsPrefabAsset(root,"Assets/wood98-"+stage+".prefab");UnityEngine.Object.DestroyImmediate(root);AssetDatabase.SaveAssets();return p;}
 public static void Run(){int exit=0;string output=Path.Combine(Root,"Evidence98Import");Directory.CreateDirectory(output);try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var before=Build("before");var after=Build("after");foreach(var id in new[]{"supplycrate","smallbarrel"}){var a=before[id].GetComponent<MeshCollider>().sharedMesh;var b=after[id].GetComponent<MeshCollider>().sharedMesh;Check(a.vertices.SequenceEqual(b.vertices)&&a.triangles.SequenceEqual(b.triangles),"collider exact "+id);}foreach(var id in before.Keys.Where(x=>x!="smallbarrel"))Check(before[id].GetComponent<MeshFilter>().sharedMesh==after[id].GetComponent<MeshFilter>().sharedMesh,"unrelated mesh exact "+id);var m=after["smallbarrel"].GetComponent<MeshFilter>().sharedMesh;Check(m.vertexCount/3<=1500,"barrel triangle budget");Check(m.vertices.All(v=>float.IsFinite(v.x)&&float.IsFinite(v.y)&&float.IsFinite(v.z)),"finite geometry");var atex=before["smallbarrel"].GetComponent<Renderer>().sharedMaterial.GetTexture("_BaseMap");var btex=after["smallbarrel"].GetComponent<Renderer>().sharedMaterial.GetTexture("_BaseMap");Check(atex==btex&&btex.width==1024&&btex.height==512,"existing shared atlas exact");File.WriteAllText(Path.Combine(output,"checks.json"),"{\"pass\":true,\"cases\":[\"before\",\"after\"],\"prefabsPerCase\":43,\"placementsPerCase\":2,\"colliderExact\":true,\"unrelatedMeshesExact\":true,\"sameAtlasObject\":true,\"newTextureBytes\":0,\"readerSourceUnchanged\":true,\"playerExecuted\":false}");}catch(Exception e){Debug.LogException(e);File.WriteAllText(Path.Combine(output,"error.txt"),e.ToString());exit=1;}finally{EditorApplication.Exit(exit);}}
}
